import json, os
from collections import Counter

roots = {
 "build-arena": "/home/leonb/projects/build-arena/docs/verification/2026-06-04-ai-first-project-decomposer-pilot-build-arena/probe-controls-current",
 "fmc-mcp": "/home/leonb/projects/build-arena/docs/verification/2026-06-04-ai-first-project-decomposer-pilot-fmc-mpc/probe-controls-current",
 "held-out": "/home/leonb/projects/build-arena/docs/verification/2026-06-04-ai-first-project-decomposer-pilot-held-out/probe-controls-current",
}
for label, root in roots.items():
    print("=" * 70)
    print("ARENA:", label)
    print("=" * 70)
    for probe in sorted(os.listdir(root)):
        pdir = os.path.join(root, probe)
        if not os.path.isdir(pdir):
            continue
        print("\n###", probe)
        for kind in ("golden", "planted-negative"):
            kdir = os.path.join(pdir, kind)
            if not os.path.isdir(kdir):
                continue
            reps = []
            for s in sorted(os.listdir(kdir)):
                grp = os.path.join(kdir, s, "gate-report.json")
                if os.path.exists(grp):
                    d = json.load(open(grp))
                    reps.append((s, d["passed"], [v["gate"] for v in d["violations"]]))
            passes = sorted({r[1] for r in reps})
            print("  [%s] n_snaps=%d passed_set=%s" % (kind, len(reps), passes))
            if reps:
                print("     gates:", dict(Counter(reps[0][2])))

